import{_ as a,o as r,c as o,a0 as t}from"./chunks/framework.BPYRhTv9.js";const g=JSON.parse('{"title":"Product Roadmap","description":"","frontmatter":{"title":"Product Roadmap"},"headers":[],"relativePath":"reference/roadmap.md","filePath":"reference/roadmap.md"}'),n={name:"reference/roadmap.md"};function i(s,e,l,d,c,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p><em>Last updated: Jul 17, 2026</em></p><p>This roadmap outlines what we&#39;re building next and what we&#39;ve recently shipped. Priorities and timelines are subject to change.</p><h3 id="planned" tabindex="-1">Planned <a class="header-anchor" href="#planned" aria-label="Permalink to &quot;Planned&quot;">​</a></h3><ul><li><strong>Vault improvements</strong> — Download and share cards directly from your vault, with sort, search, and better organization tools.</li><li><strong>Pro Calendar Drawer</strong> — Browse upcoming occasions on a calendar and create occasion cards with one tap (Pro only).</li><li><strong>Key Status Page</strong> — View your Pro key tier, expiry date, and purchase history at a glance (Pro only).</li></ul><h3 id="considering" tabindex="-1">Considering <a class="header-anchor" href="#considering" aria-label="Permalink to &quot;Considering&quot;">​</a></h3><ul><li><strong>Batch create</strong> — Write or record once and generate cards in all 7 tone styles at once.</li></ul><h3 id="recently-shipped" tabindex="-1">Recently Shipped <a class="header-anchor" href="#recently-shipped" aria-label="Permalink to &quot;Recently Shipped&quot;">​</a></h3><ul><li><strong>Wibe Pass pricing</strong> — Stackable credit system replacing subscriptions. Four tiers from $6 to $60.</li><li><strong>Pro vault</strong> — Server-side card storage with Neon Postgres, 50-card limit, cross-device sync via Pro key.</li><li><strong>Occasion email campaigns</strong> — Daily occasion reminders for 30 global dates.</li><li><strong>Custom color picker</strong> — Full color wheel with sliders for Pro users.</li><li><strong>46 speech languages, 11 UI locales</strong> — Expanded language support.</li><li><strong>7 tone styles</strong> — Preview and commit rewrite flow with per-tone daily limits.</li></ul>',9)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
